TEST(PearsonLocalCpu, ThrowsOnInputSizeMismatch) {
  std::vector<double> data(54);
  const std::size_t M = 11;
  const std::size_t N = 5;

  std::vector<double> dist_matix;
  ASSERT_THAT(
    [&](){correlate::pearson::local_cpu(dist_matix, data, M, N); },
    testing::ThrowsMessage<std::invalid_argument>("pearson::local_cpu - data size does not equal M * N")
  );
}

TEST(PearsonLocalCpu, ThrowsOnOutputSizeMismatch) {
  std::vector<double> data(55);
  const std::size_t M = 11;
  const std::size_t N = 5;

  std::vector<double> dist_matix;
    ASSERT_THAT(
    [&](){correlate::pearson::local_cpu(dist_matix, data, M, N); },
    testing::ThrowsMessage<std::invalid_argument>("pearson::local_cpu - out size does not equal N * N")
  );
}

